-- Generated from the Python v2 backend with synthetic data only.
BEGIN TRANSACTION;
CREATE TABLE entities(kind TEXT, id TEXT, doc TEXT NOT NULL, PRIMARY KEY(kind,id));
CREATE TABLE events(id INTEGER PRIMARY KEY, session_id TEXT REFERENCES sessions(id) ON DELETE CASCADE, at TEXT, kind TEXT, detail TEXT);
CREATE TABLE reports(id INTEGER PRIMARY KEY, session_id TEXT REFERENCES sessions(id) ON DELETE CASCADE, at TEXT, body TEXT);
CREATE TABLE sessions(id TEXT PRIMARY KEY, deployment_id TEXT, created_at TEXT, ip TEXT, ua TEXT, snapshot TEXT, outcome TEXT DEFAULT 'unknown', note TEXT DEFAULT '');
CREATE TABLE settings(id INTEGER PRIMARY KEY CHECK(id=1), doc TEXT NOT NULL);
CREATE TABLE versions(profile_id TEXT, version INTEGER, doc TEXT NOT NULL, PRIMARY KEY(profile_id,version));
CREATE INDEX event_session ON events(session_id);
CREATE INDEX report_session ON reports(session_id);
CREATE INDEX session_time ON sessions(created_at);
COMMIT;
